import {InvalidArgumentError} from "./errors"

/**
 * Validate the argument of a `withDigits` call: `null` (default display) or an integer
 * from 0 to 100 (the range accepted by `Number.prototype.toFixed`).
 * @throws {InvalidArgumentError} otherwise.
 */
export function assertDigits(digits: number | null): number | null {
    if (digits !== null && (!Number.isInteger(digits) || digits < 0 || digits > 100)) {
        throw new InvalidArgumentError(`withDigits expects null or an integer from 0 to 100, got: ${digits}`)
    }
    return digits
}

export function wrapParenthesis(str: string, tex = true): string {
    return tex ? `\\left( ${str} \\right)` : `(${str})`
}

/**
 * Removes the outermost parentheses only if they wrap the entire expression.
 * `(a)(b)` is left unchanged — the opening paren closes before the end.
 */
export function stripParenthesis(str: string): string {
    if (!str.startsWith('(') || !str.endsWith(')')) return str

    let depth = 0
    for (let i = 0; i < str.length - 1; i++) {
        if (str[i] === '(') depth++
        else if (str[i] === ')') depth--
        if (depth === 0) return str
    }

    return str.slice(1, -1)
}


/**
 * Replaces every occurrence of `search` with `target` in a copy of `haystack`.
 * `start` and `end` are inclusive indices; elements outside that range are left unchanged.
 */
export function replace_in_array(haystack: string[], search: string, target: string, start?: number, end?: number): string[] {
    return haystack.map((x, index) => {
        if (start !== undefined && index < start) {
            return x
        }
        if (end !== undefined && index > end) {
            return x
        }
        return x === search ? target : x
    })
}

export function splitIfOutsideParentheses(
    value: string,
    splitChar: string,
): string[] {
    if (splitChar.length !== 1) {
        throw new InvalidArgumentError(`splitChar must be a single character, got: "${splitChar}"`)
    }

    let depth = 0
        let lastIndex = 0
    const result: string[] = []

    for (let i = 0; i < value.length; i++) {
        const ch = value[i]
        if (ch === "(") depth++
        else if (ch === ")") depth--
        else if (ch === splitChar && depth === 0) {
            result.push(value.substring(lastIndex, i))
            lastIndex = i + 1
        }
    }

    result.push(value.substring(lastIndex))

    return result
}
